use nepl3_core::{budget::*,source::*,value::NdfValue};
use nepl3_doc_core::{model::*,pages::*,prepare::DocRequirement,portable,check::Category,lower};
use nepl3_wire::foundation::FoundationCodec;
use nepl3_tools::doc::source::{compiled,budget,with_named_input};
fn err(e:impl core::fmt::Debug)->String{format!("{e:?}")}
fn main()->Result<(),String>{let compiled=compiled()?;let r=&compiled.doc.registry;
let inputs=[
 ("intro","docs/start.nepld","manual/start/index.html","p",r#"article ja "[??/????]" body cons paragraph cons sentence cons anchor same text "I" cons link page "guide" some "same" text "guide" nil nil nil"#),
 ("guide","docs/nested/guide.nepld","manual/guide/index.html","p:0",r#"article ja "{??/note}" body cons section same "Guide" body cons paragraph cons sentence cons link relative ".././start.nepld" some "same" text "back" nil nil nil nil"#),
 ("extra","docs/extra.nepld","manual/extra/index.html","p:0:1",r#"article ja "Extra" body cons code Math root 0 9 cons image asset "image" none "alt" none cons paragraph cons sentence cons link external "https://example.invalid/" text "external" nil nil nil"#),
];
let mut pages=Vec::new();
for (id,source,route,name,input)in inputs {
 let make=|native|with_named_input(native,&compiled,input,name,"Article",|tree,profile,b,a|{let checked=tree.tree().bundle.validate_with_sources(profile.registry(),b,a).map_err(err)?;let empty=SourceStore::default();let mut admission=SourceAdmission::default();let mut codec=FoundationCodec::new(profile.registry(),&empty,&mut admission).map_err(err)?;lower::document(&checked,&compiled.doc.package.schema,Category::Article,profile.registry(),&mut budget(),&mut codec).map_err(err)});
 let native=make(true)?;let owned=make(false)?;assert_eq!(native,owned);assert_eq!(native.sources[0].identity().source.0,name);
 pages.push(PageDocument{registration:PageRegistration{id:id.into(),source:source.into(),route:route.into()},document:native});
}
let set=PageSet{pages};let original=set.clone();let mut seen=std::collections::BTreeMap::new();
for page in &set.pages{for source in &page.document.sources{let key=(source.identity().source.0.clone(),source.identity().revision);assert!(seen.insert(key,source.text().to_string()).is_none(),"different page source namespaces collided");}}
let empty=SourceStore::default();let mut a=SourceAdmission::default();let mut codec=FoundationCodec::new(r,&empty,&mut a).map_err(err)?;let mut b=budget();let checked=resolve(&set,r,&mut codec,&mut b).map_err(err)?;let plan=checked.plan().clone();assert_eq!(plan.links.iter().map(|x|(x.page,x.target,x.fragment.as_deref())).collect::<Vec<_>>(),vec![(0,1,Some("same")),(1,0,Some("same"))]);assert_eq!(plan.remaining.len(),3);assert!(plan.remaining.iter().all(|x|x.page==2));assert!(plan.remaining.iter().any(|x|matches!(x.requirement,DocRequirement::Foreign{..})));assert!(plan.remaining.iter().any(|x|matches!(x.requirement,DocRequirement::Asset{..})));assert!(plan.remaining.iter().any(|x|matches!(x.requirement,DocRequirement::Link{..})));
let value=portable::pages::set_to_value(&set,r,&mut codec,&mut b).map_err(err)?;let bytes=nepl3_wire::encode(&value,&mut budget()).map_err(err)?;let mut digest_input=b"NEPL3.Doc.Pages.v1\0".to_vec();digest_input.extend_from_slice(&bytes);assert_eq!(plan.identity,Digest::of(&digest_input));
let raw_plan=portable::pages::plan_to_value(&plan,&set,r,&mut codec,&mut budget()).map_err(err)?;let plan_bytes=nepl3_wire::encode(&raw_plan,&mut budget()).map_err(err)?;
let mut fresh_a=SourceAdmission::default();let mut fresh=FoundationCodec::new(r,&empty,&mut fresh_a).map_err(err)?;let mut operation=budget();let received=portable::pages::set_from_value(&nepl3_wire::decode(&bytes,&mut operation).map_err(err)?,r,&mut fresh,&mut operation).map_err(err)?;let decoded=portable::pages::plan_from_value(&nepl3_wire::decode(&plan_bytes,&mut operation).map_err(err)?,&received,r,&mut fresh,&mut operation).map_err(err)?;assert_eq!(decoded,plan);assert_eq!(operation.usage().source_bytes,set.pages.iter().flat_map(|p|p.document.sources.iter()).map(|s|s.text().len()as u64).sum::<u64>());
for i in 0..8{let mut changed=raw_plan.clone();let NdfValue::Record(p)=&mut changed else{panic!()};match i{0=>p.fields[0]=NdfValue::Bytes(vec![7;32]),1=>p.fields[1]=NdfValue::List(vec![]),2=>p.fields[2]=NdfValue::List(vec![]),3=>{let NdfValue::List(ls)=&mut p.fields[1]else{panic!()};ls.reverse();},_=>{let NdfValue::List(ls)=&mut p.fields[1]else{panic!()};let NdfValue::Record(l)=&mut ls[0]else{panic!()};l.fields[if i==4{0}else if i==5{1}else if i==6{2}else{3}]=if i==7{NdfValue::Some(Box::new(NdfValue::Text("other".into())))}else{NdfValue::U64(u64::MAX)};}}let packet=nepl3_wire::encode(&changed,&mut budget()).map_err(err)?;let raw=nepl3_wire::decode(&packet,&mut budget()).map_err(err)?;assert!(portable::pages::plan_from_value(&raw,&received,r,&mut fresh,&mut budget()).is_err());}
for i in 0..3{let mut changed=set.clone();match i{0=>changed.pages[0].registration.route="moved/index.html".into(),1=>changed.pages.reverse(),_=>{let n=changed.pages[0].document.value.nodes.iter_mut().find(|n|matches!(&n.kind,DocKind::Text{text}if text=="I")).unwrap();n.kind=DocKind::Text{text:"Changed".into()};}}let mut admission=SourceAdmission::default();let mut c=FoundationCodec::new(r,&empty,&mut admission).map_err(err)?;assert!(portable::pages::plan_from_value(&raw_plan,&changed,r,&mut c,&mut budget()).is_err());}
// Valid typed sources with the same identity but a different locator cannot be merged.
let mut collision=set.clone();let source=collision.pages[0].document.sources[0].clone();collision.pages[1].document.sources.push(SourceSnapshot::new(source.identity().source.clone(),source.identity().revision,"memory:other".into(),source.text().as_bytes().to_vec(),&mut budget()).map_err(err)?);let mut aa=SourceAdmission::default();let mut cc=FoundationCodec::new(r,&empty,&mut aa).map_err(err)?;assert!(resolve(&collision,r,&mut cc,&mut budget()).is_err());
// Missing document-local source declarations cannot use ambient entries from earlier operations.
let mut missing=value.clone();let NdfValue::Record(s)=&mut missing else{panic!()};let NdfValue::List(ps)=&mut s.fields[0]else{panic!()};let NdfValue::Record(p)=&mut ps[0]else{panic!()};let NdfValue::Record(doc)=&mut p.fields[1]else{panic!()};let source_index=1;doc.fields[source_index]=NdfValue::List(vec![]);assert!(portable::pages::set_from_value(&missing,r,&mut codec,&mut budget()).is_err());
assert_eq!(set,original);
let large=include_str!("C:/projects/NEPL3-runtime/.tmp/review-doc-pages/workspace/examples/document/linear-combination.nepld");let output=nepl3_tools::doc::export::generate(&compiled,large)?;assert_eq!(Digest::of(output.html.as_bytes()).0,[0x15,0x8c,0xc1,0x57,0x06,0x6c,0x05,0xa5,0x5c,0xfa,0x44,0x4a,0x9e,0x90,0xa7,0xbc,0x12,0xbf,0x98,0x05,0x44,0x92,0xf1,0xdf,0x02,0xfb,0xfc,0xb4,0x65,0xf3,0x9a,0xda]);
println!("Actual source PageSet: 3 native/owned trees equal; generated namespaces distinct; 2 exact links/3 remaining; first CBOR/source once; 8 plan mutations/3 stale cases/source URI and omission rejected; unchanged 13757-byte export HTML");Ok(())}
